package io.github.jesterportfolio.hearth.persistence;

import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.sql.*;import javax.sql.DataSource;
import io.github.jesterportfolio.hearth.administration.NativePolicyTool;
import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.inventory.*;

/** 정지 소유 fixture 파일과 실제 격리 PG만 사용한다. 운영 서비스/파일은 받지 않는다. */
public final class PlatformPolicyToolChecks {
    static <T>T await(CompletionStage<T> s)throws Exception{return s.toCompletableFuture().get(12,TimeUnit.SECONDS);}
    static void check(boolean b,String name){if(!b)throw new IllegalStateException(name);System.out.println("HEARTH_PLATFORM_CLI_CHECK PASS "+name);System.out.flush();}
    static void write(Path path,Properties p)throws Exception{try(var out=Files.newBufferedWriter(path,StandardOpenOption.CREATE_NEW)){p.store(out,"owned isolated policy tool fixture");}}
    public static void run(DataSource source,Connection c,Path root)throws Exception{
        var props=new Properties();try(var in=PlatformPolicyToolChecks.class.getResourceAsStream("/economy-demo.properties")){props.load(in);}props.setProperty("fixture-balance","0");var db=PostgresProgressStore.forModules(source,f->{});var content=EconomyContent.parse(props);var store=new EconomyStore(db,content);await(store.migrate());UUID realm=UUID.randomUUID(),group=UUID.randomUUID();await(store.openNativeRealm(realm,group,"a".repeat(64),1,true));var policy=new MarketAutomation.Policy(12,2,24,1000,2500,5000,2,5000);await(store.openController(realm,policy,true));var actor=store.context(realm,UUID.randomUUID());var slots=new byte[41][];slots[0]=new byte[]{9,8,7};var payload=InventoryPayload.pack(slots);await(store.ensureAccount(actor,InventoryPayload.pack(new byte[41][])));await(store.saveInventory(actor,0,payload));var original=await(store.account(actor));
        Path paper=Files.createDirectory(root.resolve("policy-tool-paper")),data=Files.createDirectories(paper.resolve("plugins/Hearth"));int port=new java.net.URI(c.getMetaData().getURL().substring(5)).getPort();
        Files.writeString(data.resolve("config.yml"),"survival-economy:\n  realm: "+realm+"\n  content-file: economy.properties\n  db-host: 127.0.0.1\n  db-port: "+port+"\n  db-name: hearth_s4_11\n  db-user: postgres\n  password-environment: HEARTH_ISOLATED_NATIVE_PASSWORD\n  allow-new-realm: false\nmarket-automation:\n  allow-new-controller: false\n  ai-mode: none\n  interval-ticks: 12\n  confirmations: 2\n  minimum-hold-ticks: 24\n  reserve-low-bps: 1000\n  reserve-normal-bps: 2500\n  reserve-high-bps: 5000\n  buffer-ticks: 2\n  low-stock-bps: 5000\n",StandardOpenOption.CREATE_NEW);
        write(data.resolve("economy.properties"),props);var binding=new Properties();binding.setProperty("realm",realm.toString());binding.setProperty("group",group.toString());binding.setProperty("content",content.fingerprint());binding.setProperty("worlds","a".repeat(64));write(data.resolve("native-economy.properties"),binding);var market=new Properties();market.setProperty("realm",realm.toString());market.setProperty("policy",policy.fingerprint());write(data.resolve("market-automation.properties"),market);
        var next=(Properties)props.clone();next.setProperty("good.iron_ore.base","120");Path candidate=root.resolve("economy-tool.candidate"),plan=root.resolve("economy-policy-plan");write(candidate,next);String[] args={"stage",paper.toString(),"economy",candidate.toString(),plan.toString(),"offline-confirmed"};
        Files.writeString(data.resolve("native-economy.active"),"owned fixture running marker");boolean denied=false;try{NativePolicyTool.main(args);}catch(Exception expected){denied=true;}Files.delete(data.resolve("native-economy.active"));check(denied&&!Files.exists(plan),"offline_policy_tool_refuses_running_marker_without_writing_candidate");NativePolicyTool.main(args);var manifest=new Properties();try(var in=Files.newBufferedReader(plan.resolve("manifest.properties"))){manifest.load(in);}UUID request=UUID.fromString(manifest.getProperty("request"));Files.writeString(data.resolve("native-policy-migration.pending"),request+"\n"+plan+"\n",StandardOpenOption.CREATE_NEW);EconomyPolicyMigration.swap(c,realm,request,"economy",content.fingerprint(),EconomyContent.parse(next).fingerprint(),false);
        args[0]="apply";NativePolicyTool.main(args);var updated=new EconomyStore(db,EconomyContent.parse(next));await(updated.migrate());check(await(updated.account(updated.context(realm,actor.playerId()))).equals(original)&&!Files.exists(data.resolve("native-policy-migration.pending")),"offline_tool_resumes_after_DB_commit_and_keeps_latest_wallet_inventory");args[0]="rollback";NativePolicyTool.main(args);check(await(store.account(actor)).equals(original),"offline_economic_tool_rolls_back_policy_and_binding_without_rewinding_accounts");
        Path mc=root.resolve("market-tool.candidate"),mp=root.resolve("market-policy-plan");Files.writeString(mc,"confirmations=3\n",StandardOpenOption.CREATE_NEW);String[] ma={"stage",paper.toString(),"market",mc.toString(),mp.toString(),"offline-confirmed"};NativePolicyTool.main(ma);ma[0]="apply";NativePolicyTool.main(ma);try(var s=c.prepareStatement("SELECT policy_hash FROM hearth_economy.market_controller WHERE realm_id=?")){s.setObject(1,realm);try(var r=s.executeQuery()){r.next();check(!r.getString(1).equals(policy.fingerprint()),"offline_market_tool_changes_only_reviewed_numeric_policy_and_preserves_controller");}}ma[0]="rollback";NativePolicyTool.main(ma);check(await(store.account(actor)).equals(original),"offline_market_tool_rolls_back_without_touching_inventory_or_balance");await(db.closeAsync());
    }
}
